// Block (composition) — a searchable multi-select list panel. Autocomplete adds live filtering
// over a ListBox in `multiple` selection mode; SearchField, ListBox, and Stack own all look and
// arrangement. This Block defines no tokens.
//
// Distinct from ComboBox (a searchable *dropdown* that reports a single value): this is an
// always-open panel for picking *several* flat options — a filter, tag, or audience selector.
// Panel posture: it sits inside a page, so width comes from the parent (block-contract §1b).
import { useId, type ReactNode, type Ref } from "react";
import { useFilter } from "react-aria-components";
import type { Selection } from "react-aria-components";
import { Autocomplete } from "../components/Autocomplete";
import { SearchField } from "../components/SearchField";
import { ListBox, ListBoxItem } from "../components/ListBox";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import "./MultiSelectList.css";

export interface MultiSelectListItem {
  id: string;
  label: string;
  /** Leading icon (optional). */
  icon?: ReactNode;
}

export interface MultiSelectListProps {
  /** Options to search and select. */
  items: MultiSelectListItem[];
  /** Optional section label. A Panel never defaults a page title (block-contract §1b). */
  heading?: string;
  placeholder?: string;
  /** Controlled selection (a Set of ids, or "all"). */
  selectedKeys?: Selection;
  /** Uncontrolled initial selection. */
  defaultSelectedKeys?: Selection;
  onSelectionChange?: (keys: Selection) => void;
  /** Accessible name for the list when there is no visible `heading`. */
  "aria-label"?: string;
  /** Message shown when the filter matches nothing. */
  emptyMessage?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function MultiSelectList({
  items,
  heading,
  placeholder = "Search…",
  selectedKeys,
  defaultSelectedKeys,
  onSelectionChange,
  "aria-label": ariaLabel,
  emptyMessage = "No options that match the search.",
  className,
  ref,
}: MultiSelectListProps) {
  const { contains } = useFilter({ sensitivity: "base" });
  const headingId = useId();
  const label = ariaLabel ?? heading ?? "Options";
  // The outer gap is `medium` because at `small` this stack and the inner one were BOTH 12px, so the
  // heading sat in one rhythm with the search field and the list and read as a third member rather
  // than as their heading. Judged on THIS Block's render, which is the only ground it has: a
  // tier-wide rule does not hold (`block-contract.md` §4a records why, including a counter-case
  // where raising the gap would be wrong). Nothing here generalises to another Block.
  return (
    <Stack
      as="section"
      ref={ref}
      gap="medium"
      aria-labelledby={heading ? headingId : undefined}
      aria-label={heading ? undefined : label}
      className={className ? `sd-multiselectlist ${className}` : "sd-multiselectlist"}
    >
      {heading && (
        <>
          <h2 id={headingId} className="sd-multiselectlist__heading sd-type-title-medium">
            {heading}
          </h2>
        </>
      )}
      <Autocomplete filter={contains}>
        <Stack gap="small" className="sd-multiselectlist__body">
          <SearchField
            aria-label={heading ? `Search ${heading}` : "Search"}
            placeholder={placeholder}
          />
          {/* The rows' fills bleed past the list (rule 8), so the bounded height scrolls in a ScrollArea,
              whose gutter keeps the bleed and the rings uncut, rather than on the ListBox, which clipped
              them. `both`: under the search field, the row text takes the inset and each fill spans
              the field's box line. No tab stop of its own: the ListBox inside is the keyboard's way
              in and scrolls its focused row into view (axe passes a region holding focusable content). */}
          <ScrollArea tabIndex={-1} className="sd-multiselectlist__list">
            <>
              <ListBox
                aria-label={label}
                selectionMode="multiple"
                selectedKeys={selectedKeys}
                defaultSelectedKeys={defaultSelectedKeys}
                onSelectionChange={onSelectionChange}
                renderEmptyState={() => emptyMessage}
              >
                {items.map((item) => (
                  <ListBoxItem key={item.id} id={item.id} icon={item.icon}>
                    {item.label}
                  </ListBoxItem>
                ))}
              </ListBox>
            </>
          </ScrollArea>
        </Stack>
      </Autocomplete>
    </Stack>
  );
}

/* MultiSelectList.css — .sd-multiselectlist (Block)
   Stack arranges the heading, search field, and options; SearchField and ListBox own all
   chrome, selection, and interaction. This Block defines no tokens.

   Real layout the primitives can't express: the options scroll within a bounded height so a
   long, filtered option set never grows the panel past a comfortable size (the search field
   stays put and the list scrolls under it). The ScrollArea owns the overflow and the compensated
   gutter that keeps the rows' bled fills uncut; this sets only the bound. */
.sd-multiselectlist__list {
  max-height: min(50vh, 22rem);
}
